<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api.js'
import PlayerAvatar from '../components/PlayerAvatar.vue'
const route=useRoute(),router=useRouter(),data=ref({group:null,players:[],squads:[]}),loading=ref(true),busy=ref(false),error=ref('')
const classLabels={melee:'Милик',archer:'Лучник',mage:'Маг',healer:'Хил',bard:'Бард',tank:'Танк'}
const assigned=computed(()=>new Set(data.value.squads.flatMap(s=>s.player_ids))),unassigned=computed(()=>data.value.players.filter(p=>!assigned.value.has(p.id))),playerById=computed(()=>new Map(data.value.players.map(p=>[p.id,p])))
const squadPlayers=s=>s.player_ids.map(id=>playerById.value.get(id)).filter(Boolean)
async function load(){loading.value=true;error.value='';try{data.value=(await api.get(`/api/groups/${route.params.id}/squads`)).data}catch(e){if(e.response?.status===403)return router.replace('/forbidden');error.value=e.response?.data?.message??'Не удалось загрузить состав пятёрок.'}finally{loading.value=false}}
async function createSquad(){busy.value=true;try{await api.post(`/api/groups/${route.params.id}/squads`,{});await load()}catch(e){error.value=e.response?.data?.message??'Не удалось создать группу.'}finally{busy.value=false}}
async function rename(s){const name=window.prompt('Название группы',s.name)?.trim();if(!name||name===s.name)return;try{await api.patch(`/api/groups/${route.params.id}/squads/${s.id}`,{name});await load()}catch(e){error.value=e.response?.data?.message??'Не удалось переименовать группу.'}}
async function remove(s){if(!window.confirm(`Удалить «${s.name}»? Игроки останутся в КП без распределения.`))return;await api.delete(`/api/groups/${route.params.id}/squads/${s.id}`);await load()}
async function assign(player,squadId){busy.value=true;error.value='';try{if(squadId)await api.put(`/api/groups/${route.params.id}/squads/${squadId}/players`,{player_id:player.id});else await api.delete(`/api/groups/${route.params.id}/squads/players/${player.id}`);await load()}catch(e){error.value=e.response?.data?.errors?.player_id?.[0]??e.response?.data?.message??'Не удалось изменить группу.'}finally{busy.value=false}}
function currentSquad(id){return data.value.squads.find(s=>s.player_ids.includes(id))?.id??''}
onMounted(load)
</script>
<template><section class="party-squads-page"><div class="page-heading squads-heading"><div><p class="eyebrow">КОНСТ-ПАТИ · СОСТАВ</p><h1>{{ data.group?.name??'Пятёрки' }}</h1><p>Распределите участников по боевым группам — не более 5 человек в каждой.</p></div><button class="primary" :disabled="busy||loading" @click="createSquad">+ Добавить группу</button></div><p v-if="error" class="notice error">{{ error }}</p><div v-if="loading" class="panel squads-loading">Загружаем состав…</div><template v-else><div v-if="data.squads.length" class="squads-grid"><article v-for="(squad,index) in data.squads" :key="squad.id" class="panel squad-card"><header><div><span>ГРУППА {{ String(index+1).padStart(2,'0') }}</span><h2>{{ squad.name }}</h2></div><b :class="{full:squad.player_ids.length===5}">{{ squad.player_ids.length }} / 5</b></header><div class="squad-list"><div v-for="player in squadPlayers(squad)" :key="player.id" class="squad-player"><PlayerAvatar :player="player" size="small"/><RouterLink :to="`/players/${player.id}`"><strong>{{ player.nickname }}</strong><small>ГС {{ Number(player.gear_score||0).toLocaleString('ru-RU') }} · {{ player.attendance_percentage }}%</small></RouterLink><span :class="['class-tag',`class-${player.class}`]">{{ classLabels[player.class] }}</span><select :value="currentSquad(player.id)" :disabled="busy" aria-label="Переместить игрока" @change="assign(player,Number($event.target.value)||null)"><option value="">Без группы</option><option v-for="target in data.squads" :key="target.id" :value="target.id" :disabled="target.player_ids.length>=5&&target.id!==squad.id">{{ target.name }}</option></select></div><div v-for="slot in 5-squad.player_ids.length" :key="`empty-${slot}`" class="squad-empty-slot"><span>+</span> Свободное место</div></div><footer><button @click="rename(squad)">Переименовать</button><button class="danger" @click="remove(squad)">Удалить</button></footer></article></div><section class="panel unassigned-panel"><div class="panel-title"><div><h2>Без группы</h2><p>{{ unassigned.length?'Участники, которых ещё нужно распределить':'Все участники распределены' }}</p></div><b>{{ unassigned.length }}</b></div><div v-if="unassigned.length" class="unassigned-list"><div v-for="player in unassigned" :key="player.id" class="squad-player"><PlayerAvatar :player="player" size="small"/><RouterLink :to="`/players/${player.id}`"><strong>{{ player.nickname }}</strong><small>ГС {{ Number(player.gear_score||0).toLocaleString('ru-RU') }} · {{ player.attendance_percentage }}%</small></RouterLink><span :class="['class-tag',`class-${player.class}`]">{{ classLabels[player.class] }}</span><select value="" :disabled="busy||!data.squads.length" aria-label="Назначить игрока" @change="assign(player,Number($event.target.value))"><option value="" disabled>Выбрать группу</option><option v-for="squad in data.squads" :key="squad.id" :value="squad.id" :disabled="squad.player_ids.length>=5">{{ squad.name }} ({{ squad.player_ids.length }}/5)</option></select></div></div></section></template></section></template>
